export const LIBRARY_FILE_CATEGORIES = [
  "document",
  "spreadsheet",
  "presentation",
  "image",
  "video",
  "audio",
  "other",
] as const;

export type LibraryFileCategory = (typeof LIBRARY_FILE_CATEGORIES)[number];

export type LibraryFileSource = "bot" | "user";

export interface LibraryFile {
  bot: {
    slug: string;
    name: string;
    avatar: string | null;
  };
  contentType: string;
  createdAt: string;
  id: string;
  name: string;
  size: number;
  /** The reference owner: files sent by the person or generated by a bot. */
  source?: LibraryFileSource;
  version: number;
}

export interface LibraryResponse {
  files: LibraryFile[];
  nextCursor: string | null;
}
